import { expect, expectStatus, test } from "../../fixtures";

test.describe("vendor list paging", () => {
  test("a page past the last vendor is empty but still reports the total", { tag: "@LIF-15" }, async ({ apiAs, factory }) => {
    // Arrange
    await factory.vendor({ as: "member" });
    const member = await apiAs("member");
    const firstPage = await expectStatus<{ items: unknown[]; total: number; limit: number; offset: number }>(
      await member.get("/api/vendors", { params: { limit: 20, offset: 0 } }),
      200,
    );
    const offset = firstPage.total + 10;

    // Act
    const response = await member.get("/api/vendors", { params: { limit: 20, offset } });

    // Assert
    const page = await expectStatus<{ items: unknown[]; total: number; limit: number; offset: number }>(response, 200);
    expect(page.items, "items past the last vendor").toEqual([]);
    expect(page.total, "total matches the first page").toBe(firstPage.total);
    expect(page.offset, "offset echoes the request").toBe(offset);
  });
});
